using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.LymeGrass;

/// <summary>
/// Lyme grass, blue-grey tussocks on the black sand along the Ashlands shore, whose grain the people of Iceland gathered
/// and baked when the barley failed. Model: generated by AssetSource/Tools/make_forage_models.py. Nothing else gives it.
/// </summary>
public class LymeGrass : ForageableBase
{
    /// <summary>
    /// Prefab name of the lyme grain item.
    /// </summary>
    public const string PrefabName = "WhiteHiltLymeGrain";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Lyme Grain";

    /// <inheritdoc/>
    protected override string Description => "Ears of lyme grass from the black sand by the sea. Small, hard grain, but where nothing else grows it makes bread.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Barley";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Thistle";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed. Only the
        // low sand by the shore.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 2,
        GroupSizeMax = 4,
        GroupRadius = 4f,
        MinAltitude = 0.5f,
        MaxAltitude = 8f,
        MaxTilt = 20f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, IsItem(visualRoot) ? "lymegrain" : "lymegrass", 1.1f);
    }

    /// <inheritdoc/>
    protected override void ApplyPickableVisual(GameObject pickablePrefab, Pickable pickable)
    {
        RemoveGlow(pickablePrefab);
        base.ApplyPickableVisual(pickablePrefab, pickable);
    }
}
